245	func TestBusinessFlowJ01IdempotentTicketCreation(t *testing.T) {
246		suite := newTicketingSuite(t)
247		key := uniqueKey("j01-create")
248		title := "J01 idempotent " + key
249		body := map[string]any{"data": map[string]any{
250			"title": title, "description": "original payload", "priority": "high",
251			"assignee_profile_id": agentAProfileID, "reporter_name": "J01 Reporter",
252		}}
253	
254		first := suite.agentA.request(t, http.MethodPost, "/objects/ticket/records", key, body)
255		requireStatusAny(t, first, http.StatusOK, http.StatusCreated)
256		firstRecord := mapBody(t, first.Body)
257		firstID := stringField(t, firstRecord, "id")
258		if firstID == "" || stringField(t, nestedMap(t, firstRecord, "data"), "status") != "new" {
259			t.Fatalf("invalid first create record: %#v", firstRecord)
260		}
261	
262		replay := suite.agentA.request(t, http.MethodPost, "/objects/ticket/records", key, body)
263		requireStatus(t, replay, http.StatusOK)
264		if replayID := stringField(t, mapBody(t, replay.Body), "id"); replayID != firstID {
265			t.Fatalf("replay ID = %q, want %q", replayID, firstID)
266		}
267	
268		changed := map[string]any{"data": map[string]any{
269			"title": title + " changed", "description": "changed payload", "priority": "low",
270			"assignee_profile_id": agentAProfileID, "reporter_name": "J01 Reporter",
271		}}
272		conflict := suite.agentA.request(t, http.MethodPost, "/objects/ticket/records", key, changed)
273		requireError(t, conflict, http.StatusConflict, "backend.idempotency.conflict")
274		durable := getTicket(t, suite.agentA, firstID)
275		if got := stringField(t, nestedMap(t, durable, "data"), "title"); got != title {
276			t.Fatalf("title after conflicting replay = %q, want %q", got, title)
277		}
278	}
