280	// J02/J03 / RQ-002,RQ-004..RQ-007,RQ-010,RQ-012: highest-risk assignment, scope, lifecycle, denial, audit and Inbox flow.
281	func TestBusinessFlowJ02J03AssignmentLifecycleAuditAndNotification(t *testing.T) {
282		suite := newTicketingSuite(t)
283		ticketID, title, _ := createTicket(t, suite.agentA, agentAProfileID, "j02-j03")
284	
285		assignKey := uniqueKey("j02-assign")
286		assignBody := map[string]any{"data": map[string]any{"assignee_profile_id": agentBProfileID, "request_id": assignKey}}
287		assigned := suite.manager.request(t, http.MethodPost,
288			"/objects/ticket/records/"+url.PathEscape(ticketID)+"/actions/ticket.assign_ticket", assignKey, assignBody)
289		requireStatus(t, assigned, http.StatusOK)
290		assignedOutput := nestedMap(t, mapBody(t, assigned.Body), "output")
291		if stringField(t, assignedOutput, "ticket_id") != ticketID || stringField(t, assignedOutput, "notification_receipt_id") == "" {
292			t.Fatalf("assignment output = %#v", assignedOutput)
293		}
294		assignedReplay := suite.manager.request(t, http.MethodPost,
295			"/objects/ticket/records/"+url.PathEscape(ticketID)+"/actions/ticket.assign_ticket", assignKey, assignBody)
296		requireStatus(t, assignedReplay, http.StatusOK)
297		if stringField(t, nestedMap(t, mapBody(t, assignedReplay.Body), "output"), "notification_receipt_id") != stringField(t, assignedOutput, "notification_receipt_id") {
298			t.Fatal("assignment replay returned a different notification receipt")
299		}
300	
301		formerAssigneeRead := suite.agentA.request(t, http.MethodGet, "/objects/ticket/records/"+url.PathEscape(ticketID), "", nil)
302		requireError(t, formerAssigneeRead, http.StatusNotFound, "backend.record.not_found")
303		if got := stringField(t, nestedMap(t, getTicket(t, suite.agentB, ticketID), "data"), "assignee_profile_id"); got != agentBProfileID {
304			t.Fatalf("durable assignee = %q, want %q", got, agentBProfileID)
305		}
306	
307		formerStart := suite.agentA.request(t, http.MethodPost,
308			"/objects/ticket/records/"+url.PathEscape(ticketID)+"/actions/ticket.start", uniqueKey("j03-former-start"),
309			map[string]any{"data": map[string]any{"status": "in_progress"}})
310		requireError(t, formerStart, http.StatusForbidden, "backend.record.outside_scope")
311		invalidResolve := suite.agentB.request(t, http.MethodPost,
312			"/objects/ticket/records/"+url.PathEscape(ticketID)+"/actions/ticket.resolve", uniqueKey("j03-invalid-resolve"),
313			map[string]any{"data": map[string]any{"status": "resolved"}})
314		requireError(t, invalidResolve, http.StatusBadRequest, "backend.transition.invalid_transition")
315		if got := ticketStatus(t, suite.agentB, ticketID); got != "new" {
316			t.Fatalf("state after denials = %q, want new", got)
317		}
318	
319		transition(t, suite.agentB, ticketID, "ticket.start", "in_progress")
320		transition(t, suite.agentB, ticketID, "ticket.resolve", "resolved")
321		agentClose := suite.agentB.request(t, http.MethodPost,
322			"/objects/ticket/records/"+url.PathEscape(ticketID)+"/actions/ticket.close", uniqueKey("j03-agent-close"),
323			map[string]any{"data": map[string]any{"status": "closed"}})
324		requireError(t, agentClose, http.StatusForbidden, "backend.action.permission_denied")
325		if got := ticketStatus(t, suite.manager, ticketID); got != "resolved" {
326			t.Fatalf("state after denied close = %q, want resolved", got)
327		}
328		transition(t, suite.manager, ticketID, "ticket.reopen", "in_progress")
329		transition(t, suite.agentB, ticketID, "ticket.resolve", "resolved")
330		transition(t, suite.manager, ticketID, "ticket.close", "closed")
331		if got := ticketStatus(t, suite.manager, ticketID); got != "closed" {
332			t.Fatalf("terminal state = %q, want closed", got)
333		}
334	
335		notifications := suite.agentB.request(t, http.MethodGet, "/business/notifications", "", nil)
336		requireStatus(t, notifications, http.StatusOK)
337		foundNotification := false
338		for _, item := range nestedSlice(t, mapBody(t, notifications.Body), "items") {
339			entry := mapBody(t, item)
340			if entry["event_type"] == "ticket.assigned" && (entry["body"] == "工单「"+title+"」已分派给你处理。" || strings.Contains(fmt.Sprint(entry["body"]), title)) {
341				foundNotification = true
342			}
343		}
344		if !foundNotification {
345			t.Fatalf("no durable assignment notification found for %q", title)
346		}
347	
348		query := url.Values{"object_key": {"ticket"}, "record_id": {ticketID}, "page_size": {"50"}}
349		audits := suite.manager.request(t, http.MethodGet, "/business/audit-events?"+query.Encode(), "", nil)
350		requireStatus(t, audits, http.StatusOK)
351		events := map[string]bool{}
352		for _, item := range nestedSlice(t, mapBody(t, audits.Body), "items") {
353			events[fmt.Sprint(mapBody(t, item)["event"])] = true
354		}
355		for _, event := range []string{"ticket.assigned", "notification.intent.dispatch", "ticket.started", "ticket.resolved", "ticket.reopened", "ticket.closed"} {
356			if !events[event] {
357				t.Fatalf("audit event %q missing; events=%v", event, events)
358			}
359		}
360	}
