363	func TestBusinessFlowJ04ScopedUpdateAndAppendOnlyComments(t *testing.T) {
364		suite := newTicketingSuite(t)
365		ticketID, _, _ := createTicket(t, suite.agentA, agentAProfileID, "j04")
366	
367		update := suite.agentA.request(t, http.MethodPatch, "/objects/ticket/records/"+url.PathEscape(ticketID), uniqueKey("j04-update"),
368			map[string]any{"data": map[string]any{"title": "J04 updated title", "description": "durable detail", "priority": "high"}})
369		requireStatus(t, update, http.StatusOK)
370		updatedData := nestedMap(t, mapBody(t, update.Body), "data")
371		if stringField(t, updatedData, "title") != "J04 updated title" || stringField(t, updatedData, "priority") != "high" {
372			t.Fatalf("updated data = %#v", updatedData)
373		}
374	
375		statusPatch := suite.agentA.request(t, http.MethodPatch, "/objects/ticket/records/"+url.PathEscape(ticketID), uniqueKey("j04-status-patch"),
376			map[string]any{"data": map[string]any{"status": "closed"}})
377		requireError(t, statusPatch, http.StatusBadRequest, "backend.validation.field_not_writable")
378		otherRead := suite.agentB.request(t, http.MethodGet, "/objects/ticket/records/"+url.PathEscape(ticketID), "", nil)
379		requireError(t, otherRead, http.StatusNotFound, "backend.record.not_found")
380		otherUpdate := suite.agentB.request(t, http.MethodPatch, "/objects/ticket/records/"+url.PathEscape(ticketID), uniqueKey("j04-other-update"),
381			map[string]any{"data": map[string]any{"title": "forbidden"}})
382		if otherUpdate.Status != http.StatusForbidden && otherUpdate.Status != http.StatusNotFound {
383			t.Fatalf("other-agent update status = %d, want scope denial", otherUpdate.Status)
384		}
385		durableTicket := getTicket(t, suite.agentA, ticketID)
386		if data := nestedMap(t, durableTicket, "data"); stringField(t, data, "title") != "J04 updated title" || stringField(t, data, "status") != "new" {
387			t.Fatalf("ticket changed after denial: %#v", data)
388		}
389	
390		commentContent := "J04 append-only processing note"
